f(isset($_SESSION['flash'])):?><p class="notice" role="status"><?=e($_SESSION['flash'])?></p><?php unset($_SESSION['flash']);endif;?>
<?php if($section==='dashboard'):
$stats=query("SELECT COUNT(*) total,COALESCE(SUM(a.status='pending'),0) pending,COALESCE(SUM(a.status='completed'),0) completed,COALESCE(SUM(a.status='cancelled'),0) cancelled,COALESCE(SUM(CASE WHEN a.status='completed' THEN a.price ELSE 0 END),0) revenue FROM appointments a WHERE $where AND DATE(a.starts_at)=CURDATE()",$params)->fetch();
?><div class="stats-grid"><?php foreach([['Agendamentos hoje',$stats['total'],'◷'],['Aguardando aprovação',$stats['pending'],'◴'],['Atendimentos concluídos',$stats['completed'],'✓'],['Receita realizada',money($stats['revenue']),'↗']] as [$label,$value,$icon]):?><article class="stat"><span><?=$label?><b><?=$icon?></b></span><strong><?=e($value)?></strong><small>Hoje · <?=date('d/m/Y')?></small></article><?php endforeach;?></div><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h3>Próximos atendimentos</h3><p>Os próximos encontros da sua agenda.</p></div><a class="text-link" href="<?=e(url('painel/agenda'))?>">Ver agenda ↗</a></div><?php $next=query("SELECT a.*,c.name client,s.name service,p.name professional FROM appointments a JOIN clients c ON c.id=a.client_id JOIN services s ON s.id=a.service_id JOIN professionals p ON p.id=a.professional_id WHERE $where AND a.starts_at>=NOW() AND a.status IN ('pending','confirmed') ORDER BY a.starts_at LIMIT 6",$params)->fetchAll();if(!$next):?><div class="empty"><span>▦</span><h3>Sua agenda está pronta para começar</h3><p>Cadastre serviços e profissionais e compartilhe seu link.</p></div><?php endif;foreach($next as $a):?><div class="appointment-row"><time><?=date('H:i',strtotime($a['starts_at']))?><small><?=date('d/m',strtotime($a['starts_at']))?></small></time><span class="avatar"><?=e(mb_substr($a['client'],0,1))?></span><div><b><?=e($a['client'])?></b><small><?=e($a['service'].' · '.$a['professional'])?></small></div><span class="badge <?=$a['status']?>"><?=$statusLabels[$a['status']]?></span></div><?php endforeach;?></section><div><section class="share-card"><span class="eyebrow">SUA AGENDA VAI MAIS LONGE</span><h3>Um link.<br>Muitas possibilidades.</h3><p>Compartilhe sua página e deixe seus clientes escolherem o melhor horário.</p><input readonly aria-label="Link público" value="<?=e(url('agendar/'.$est['slug']))?>"><button class="secondary" type="button" data-copy="<?=e(url('agendar/'.$est['slug']))?>">Copiar link ↗</button></section><section class="panel popular"><h3>Serviços mais agendados</h3><?php $popular=query("SELECT s.name,COUNT(*) total FROM appointments a JOIN services s ON s.id=a.service_id WHERE $where AND a.status<>'cancelled' GROUP BY s.id,s.name ORDER BY total DESC LIMIT 4",$params)->fetchAll();foreach($popular as $p):?><p class="split"><span><?=e($p['name'])?></span><b><?=$p['total']?></b></p><?php endforeach;if(!$popular):?><p class="muted">Os destaques aparecerão após as primeiras reservas.</p><?php endif;?><p class="muted"><?=$stats['cancelled']?> cancelamento(s) hoje.</p></section></div></div>
<?php elseif(in_array($section,['agenda','agendamentos'])):
$date=(string)($_GET['date']??date('Y-m-d'));if(!app\Services\Availability::validDate($date))$date=date('Y-m-d');$mode=$_GET['mode']??'day';$start=$date;$end=date('Y-m-d',strtotime($date.' +1 day'));
if($mode==='week'){$start=date('Y-m-d',strtotime('monday this week',strtotime($date)));$end=date('Y-m-d',strtotime($start.' +7 days'));}elseif($mode==='month'){$start=date('Y-m-01',strtotime($date));$end=date('Y-m-d',strtotime($start.' +1 month'));}
$search=trim($_GET['q']??'');$w=$where.' AND a.starts_at>=? AND a.starts_at<?';$p=[...$params,$start,$end];if($search!==''){$w.=' AND c.name LIKE ?';$p[]='%'.$search.'%';}
$appointments=query("SELECT a.*,c.name client,c.phone,s.name service,p.name professional FROM appointments a JOIN clients c ON c.id=a.client_id JOIN services s ON s.id=a.service_id JOIN professionals p ON p.id=a.professional_id WHERE $w ORDER BY a.starts_at",$p)->fetchAll();
?><form class="filterbar" method="get"><label>Data<input type="date" name="date" value="<?=e($date)?>"></label><label>Visualização<select name="mode"><?php foreach(['day'=>'Dia','week'=>'Semana','month'=>'Mês'] as $v=>$l):?><option value="<?=$v?>" <?=$mode===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><?php if($u['role']==='admin'):?><label>Profissional<?php $proSelect('professional',$filterPro);?></label><?php endif;?><label>Pesquisar cliente<input name="q" value="<?=e($search)?>" placeholder="Nome do cliente"></label><button>Filtrar</button></form>
<section class="panel"><div class="panel-heading"><h3><?=date('d/m/Y',strtotime($start))?> — <?=date('d/m/Y',strtotime($end.' -1 day'))?></h3><span class="muted"><?=count($appointments)?> agendamento(s)</span></div><?php $calendarDates=[];for($cd=$start;$cd<$end;$cd=date('Y-m-d',strtotime($cd.' +1 day')))$calendarDates[]=$cd;?><div class="agenda-list calendar-<?=e($mode)?>"><?php foreach($calendarDates as $calendarDay):?><section class="calendar-day"><h4><?=date('d/m',strtotime($calendarDay))?> · <?=$days[(int)date('w',strtotime($calendarDay))]?></h4><?php $dayAppointments=array_filter($appointments,fn($row)=>substr($row['starts_at'],0,10)===$calendarDay);foreach($dayAppointments as $a):?><article class="agenda-entry"><div class="agenda-time"><b><?=date('H:i',strtotime($a['starts_at']))?></b><small><?=date('d/m',strtotime($a['starts_at']))?> · até <?=date('H:i',strtotime($a['ends_at']))?></small></div><div class="agenda-card"><div class="split"><h3><?=e($a['client'])?></h3><span class="badge <?=$a['status']?>"><?=$statusLabels[$a['status']]?></span></div><p><?=e($a['service'].' · '.$a['professional'])?> <b><?=money($a['price'])?></b></p><div class="actions wrap"><form method="post" class="inline-form"><?=$token?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$a['id']?>"><select name="status" aria-label="Novo status"><?php foreach($statusLabels as $v=>$l):?><option value="<?=$v?>" <?=$a['status']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select><button class="small secondary">Atualizar</button></form><?php $msg=strtr($settings['message_template'],['{cliente}'=>$a['client'],'{servico}'=>$a['service'],'{estabelecimento}'=>$est['name'],'{status}'=>mb_strtolower($statusLabels[$a['status']]),'{data}'=>date('d/m/Y',strtotime($a['starts_at'])),'{hora}'=>date('H:i',strtotime($a['starts_at']))]);?><a class="text-link" target="_blank" rel="noreferrer" href="https://wa.me/<?=e(strlen($a['phone'])<=11?'55'.$a['phone']:$a['phone'])?>?text=<?=rawurlencode($msg)?>">WhatsApp ↗</a><a href="<?=e(url('painel/agendamentos?reschedule='.$a['id'].'#novo'))?>">Reagendar</a></div></div></article><?php endforeach;if(!$dayAppointments):?><p class="calendar-empty">Sem agendamentos</p><?php endif;?></section><?php endforeach;if(!$appointments && $mode==='day'):?><div class="empty"><span>◷</span><h3>Um espaço livre na sua rotina</h3><p>Nenhum agendamento para este filtro.</p></div><?php endif;?></div></section>
<?php $edit=null;if(!empty($_GET['reschedule'])){$edit=query("SELECT a.*,c.name client,c.phone,c.email FROM appointments a JOIN clients c ON c.id=a.client_id WHERE $where AND a.id=?",[...$params,(int)$_GET['reschedule']])->fetch();if(!$edit)throw new RuntimeException('Reserva não encontrada.',404);}?>
<section class="panel" id="novo"><h3><?=$edit?'Reagendar atendimento':'Novo agendamento'?></h3><p class="muted">A disponibilidade é verificada novamente ao salvar. Informe uma data e horário dentro da grade de atendimento.</p><form method="post" class="form-grid"><?=$token?><input type="hidden" name="action" value="booking"><input type="hidden" name="reschedule" value="<?=$edit['id']??0?>"><label>Serviço<select name="service" required><?php foreach($services as $s):if(!$s['active'])continue;?><option value="<?=$s['id']?>" <?=($edit['service_id']??0)==$s['id']?'selected':''?>><?=e($s['name'])?> · <?=$s['duration']?> min</option><?php endforeach;?></select></label><label>Profissional<select name="professional"><?php if($u['role']==='admin'):?><option value="0">Qualquer disponível</option><?php endif;foreach($pros as $pro):if($u['role']==='professional' && $pro['id']!=$u['professional_id'])continue;?><option value="<?=$pro['id']?>" <?=($edit['professional_id']??0)==$pro['id']?'selected':''?>><?=e($pro['name'])?></option><?php endforeach;?></select></label><label>Data<input type="date" name="date" required value="<?=e($edit?substr($edit['starts_at'],0,10):$date)?>"></label><label>Horário<input type="time" name="time" required value="<?=e($edit?substr($edit['starts_at'],11,5):'')?>"></label><label>Nome do cliente<input name="name" required value="<?=e($edit['client']??'')?>"></label><label>WhatsApp<input type="tel" name="phone" required value="<?=e($edit['phone']??'')?>"></label><label>E-mail (opcional)<input type="email" name="email" value="<?=e($edit['email']??'')?>"></label><div class="form-end"><button><?=$edit?'Salvar novo horário':'Criar agendamento'?></button></div></form></section>
<?php elseif($section==='servicos'): ?>
<div class="management-grid"><?php foreach($services as $s):$assigned=array_column(query('SELECT professional_id FROM professional_services WHERE establishment_id=? AND service_id=?',[$t,$s['id']])->fetchAll(),'professional_id');?><details class="panel"><summary><b><?=e($s['name'])?></b><span><?=money($s['price'])?> · <?=$s['duration']?> min · <?=$s['active']?'Ativo':'Inativo'?></span></summary><?php service_form($s,$assigned,$pros,$token);?><form method="post" data-confirm="Arquivar este serviço? O histórico será preservado."><?=$token?><input type="hidden" name="action" value="delete_service"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="danger small">Arquivar serviço</button></form></details><?php endforeach;?></div><section class="panel"><h3>Adicionar serviço</h3><?php service_form([],[],$pros,$token);?></section>
