<?php elseif($section==='horarios'):$pid=(int)($_GET['professional_id']??0);app\Services\Management::professional($t,$pid);$hours=query($pid?'SELECT * FROM professional_working_hours WHERE establishment_id=? AND professional_id=?':'SELECT * FROM business_hours WHERE establishment_id=?',$pid?[$t,$pid]:[$t])->fetchAll();$hours=array_column($hours,null,'weekday');?><form method="get" class="filterbar"><label>Configurar horários de<?php $proSelect('professional_id',$pid);?></label><button>Selecionar</button></form><section class="panel"><h3>Expediente semanal</h3><p class="muted">Horários individuais também respeitam o expediente do estabelecimento. Sem configuração individual, o profissional segue o estabelecimento.</p><form method="post"><?=$token?><input type="hidden" name="action" value="hours"><input type="hidden" name="professional_id" value="<?=$pid?>"><?php foreach($days as $d=>$label):$h=$hours[$d]??['opens'=>'08:00','closes'=>'18:00','closed'=>0];?><div class="hours-row"><b><?=$label?></b><label>Abertura<input type="time" name="opens[<?=$d?>]" value="<?=substr($h['opens'],0,5)?>" required></label><label>Fechamento<input type="time" name="closes[<?=$d?>]" value="<?=substr($h['closes'],0,5)?>" required></label><label class="checkbox"><input type="checkbox" name="closed[<?=$d?>]" <?=$h['closed']?'checked':''?>>Fechado</label></div><?php endforeach;?><button>Salvar expediente</button></form></section><div class="management-grid"><section class="panel"><h3>Intervalos de descanso</h3><form method="post" class="form-stack"><?=$token?><input type="hidden" name="action" value="break"><label>Aplica-se a<?php $proSelect();?></label><label>Dia da semana<select name="weekday"><?php foreach($days as $d=>$l):?><option value="<?=$d?>"><?=$l?></option><?php endforeach;?></select></label><div class="form-grid"><label>Início<input type="time" name="starts" required></label><label>Fim<input type="time" name="ends" required></label></div><button>Adicionar intervalo</button></form><?php foreach(query('SELECT b.*,p.name professional FROM breaks b LEFT JOIN professionals p ON p.id=b.professional_id WHERE b.establishment_id=? ORDER BY b.weekday,b.starts',[$t]) as $b):?><form method="post" class="split list-item"><?=$token?><input type="hidden" name="action" value="delete_break"><input type="hidden" name="id" value="<?=$b['id']?>"><span><?=e($b['professional']??'Todos')?> · <?=$days[$b['weekday']]?> · <?=substr($b['starts'],0,5)?>–<?=substr($b['ends'],0,5)?></span><button class="link-button">Remover</button></form><?php endforeach;?></section><section class="panel"><h3>Folgas, feriados e exceções</h3><form method="post" class="form-stack"><?=$token?><input type="hidden" name="action" value="exception"><label>Aplica-se a<?php $proSelect();?></label><label>Data<input type="date" name="date" required></label><label>Motivo<input name="reason" maxlength="190"></label><label class="checkbox"><input type="checkbox" name="closed" checked>Bloquear o dia inteiro</label><div class="form-grid"><label>Abertura excepcional<input type="time" name="opens"></label><label>Fechamento excepcional<input type="time" name="closes"></label></div><button>Adicionar exceção</button></form><?php foreach(query('SELECT x.*,p.name professional FROM schedule_exceptions x LEFT JOIN professionals p ON p.id=x.professional_id WHERE x.establishment_id=? ORDER BY x.date DESC',[$t]) as $x):?><form method="post" class="split list-item"><?=$token?><input type="hidden" name="action" value="delete_exception"><input type="hidden" name="id" value="<?=$x['id']?>"><span><?=e($x['professional']??'Todos')?> · <?=date('d/m/Y',strtotime($x['date']))?> · <?=e($x['reason'])?> (<?=$x['closed']?'Fechado':substr($x['opens'],0,5).'–'.substr($x['closes'],0,5)?>)</span><button class="link-button">Remover</button></form><?php endforeach;?></section></div>
<?php elseif($section==='clientes'):?><section class="panel"><h3>Clientes do estabelecimento</h3><form method="get" class="filterbar"><label>Pesquisar<input name="q" value="<?=e($_GET['q']??'')?>" placeholder="Nome ou WhatsApp"></label><button>Pesquisar</button></form><div class="table-scroll"><table><thead><tr><th>Nome</th><th>WhatsApp</th><th>E-mail</th><th>Reservas</th></tr></thead><tbody><?php $q='%'.trim($_GET['q']??'').'%';foreach(query('SELECT c.*,(SELECT COUNT(*) FROM appointments a WHERE a.establishment_id=c.establishment_id AND a.client_id=c.id) total FROM clients c WHERE c.establishment_id=? AND (c.name LIKE ? OR c.phone LIKE ?) ORDER BY c.name',[$t,$q,$q]) as $c):?><tr><td><?=e($c['name'])?></td><td><?=e($c['phone'])?></td><td><?=e($c['email'])?></td><td><?=$c['total']?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php elseif($section==='configuracoes'):?><section class="panel"><h3>Seu estabelecimento</h3><form method="post" enctype="multipart/form-data" class="form-grid"><?=$token?><input type="hidden" name="action" value="settings"><label>Nome<input name="name" required value="<?=e($est['name'])?>"></label><label>Categoria<input name="category" required value="<?=e($est['category'])?>"></label><label>WhatsApp<input name="phone" required value="<?=e($est['phone'])?>"></label><label>Endereço<input name="address" maxlength="255" value="<?=e($est['address'])?>"></label><label class="full">Descrição<textarea name="description" rows="3"><?=e($est['description'])?></textarea></label><label>Logo (JPG, PNG, WebP até 2 MB)<input type="file" name="logo" accept="image/jpeg,image/png,image/webp"></label><label>Antecedência mínima (minutos)<input type="number" name="min_notice" min="0" max="525600" required value="<?=$settings['min_notice']?>"></label><label>Dias futuros disponíveis<input type="number" name="max_days" min="1" max="365" required value="<?=$settings['max_days']?>"></label><label>Intervalo entre inícios (minutos)<input type="number" name="slot_step" min="5" max="120" required value="<?=$settings['slot_step']?>"></label><label class="checkbox"><input type="checkbox" name="auto_confirm" <?=$settings['auto_confirm']?'checked':''?>>Confirmar reservas automaticamente</label><label class="checkbox"><input type="checkbox" name="cancelled_releases" <?=$settings['cancelled_releases']?'checked':''?>>Cancelamentos liberam o horário</label><label class="full">Modelo da mensagem do WhatsApp<textarea name="message_template" rows="4" maxlength="2000" required><?=e($settings['message_template'])?></textarea><small>Use {cliente}, {servico}, {estabelecimento}, {status}, {data}, {hora}. O envio é manual.</small></label><button>Salvar configurações</button></form></section><?php endif;?>
