function service_form(array $s,array $assigned,array $pros,string $token): void { ?><form method="post" enctype="multipart/form-data" class="form-grid"><?=$token?><input type="hidden" name="action" value="service"><input type="hidden" name="id" value="<?=$s['id']??0?>"><label>Nome<input name="name" required value="<?=e($s['name']??'')?>"></label><label>Preço (R$)<input type="number" name="price" min="0" step="0.01" required value="<?=e($s['price']??'')?>"></label><label>Duração (minutos)<input type="number" name="duration" min="5" max="720" required value="<?=$s['duration']??30?>"></label><label>Tempo adicional após serviço<input type="number" name="buffer" min="0" max="240" value="<?=$s['buffer']??0?>"></label><label class="full">Descrição<textarea name="description"><?=e($s['description']??'')?></textarea></label><label>Imagem opcional<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><fieldset><legend>Profissionais habilitados</legend><?php foreach($pros as $p):?><label class="checkbox"><input type="checkbox" name="professionals[]" value="<?=$p['id']?>" <?=in_array($p['id'],$assigned)?'checked':''?>><?=e($p['name'])?></label><?php endforeach;if(!$pros):?><p>Cadastre um profissional primeiro.</p><?php endif;?></fieldset><label class="checkbox"><input type="checkbox" name="active" <?=($s['active']??1)?'checked':''?>>Serviço ativo</label><button>Salvar serviço</button></form><?php }
function professional_form(array $p,string $token): void { ?><form method="post" class="form-grid"><?=$token?><input type="hidden" name="action" value="professional"><input type="hidden" name="id" value="<?=$p['id']??0?>"><label>Nome<input name="name" required value="<?=e($p['name']??'')?>"></label><label>Especialidade<input name="specialty" value="<?=e($p['specialty']??'')?>"></label><label>E-mail de acesso (opcional)<input type="email" name="email" autocomplete="off"></label><label>Senha de acesso (mínimo 10 caracteres)<input type="password" name="password" minlength="10" autocomplete="new-password"><small>Preencha e-mail e senha para criar ou renovar o acesso individual.</small></label><label class="checkbox"><input type="checkbox" name="active" <?=($p['active']??1)?'checked':''?>>Profissional ativo</label><button>Salvar profissional</button></form><?php }
